# Let's solve the Sudoku puzzle using backtracking

# Define the grid with given clues
grid = [0] * 81

clues = {
    2: 3,
    11: 6,
    13: 8,
    20: 9,
    22: 2,
    35: 7,
    42: 2,
    46: 9,
    50: 4,
    57: 6,
    58: 4,
    60: 9,
    62: 8,
    69: 5,
    78: 6,
    79: 4
}

for idx, val in clues.items():
    grid[idx] = val

# Helper functions
def get_row(idx):
    return idx // 9

def get_col(idx):
    return idx % 9

def get_block(idx):
    r = get_row(idx)
    c = get_col(idx)
    return (r // 3) * 3 + (c // 3)

# Precompute neighbors for each cell
neighbors = [set() for _ in range(81)]
for i in range(81):
    ri, ci, bi = get_row(i), get_col(i), get_block(i)
    for j in range(81):
        if i == j:
            continue
        rj, cj, bj = get_row(j), get_col(j), get_block(j)
        if ri == rj or ci == cj or bi == bj:
            neighbors[i].add(j)

# Check if a value is valid at a position
def is_valid(grid, idx, val):
    for nb in neighbors[idx]:
        if grid[nb] == val:
            return False
    return True

# Find empty cell with fewest possibilities (MRV)
def find_empty(grid):
    best_idx = -1
    best_options = None
    for i in range(81):
        if grid[i] != 0:
            continue
        options = []
        for v in range(1, 10):
            if is_valid(grid, i, v):
                options.append(v)
        if not options:
            return i, []  # dead end
        if best_options is None or len(options) < len(best_options):
            best_idx = i
            best_options = options
            if len(options) == 1:
                break
    return best_idx, best_options

# Backtracking solver
def solve(grid):
    idx, options = find_empty(grid)
    if idx == -1:
        return True  # solved
    if not options:
        return False
    for val in options:
        grid[idx] = val
        if solve(grid):
            return True
        grid[idx] = 0
    return False

# Solve
solution_grid = grid[:]
if solve(solution_grid):
    print("Solved!")
    # Print in 9x9 format
    for r in range(9):
        print(solution_grid[r*9:(r+1)*9])
    print("\nSolution list:")
    print(solution_grid)
else:
    print("UNSATISFIABLE")
